-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM analytics_metric_triggers WHERE metric_key IN ('pm_breaker_active','pm_brier_gain','pm_shadow_roi','pm_graduation_ready'); DELETE FROM metric_breach_cause WHERE metric_key IN ('pm_paper_return_pct','pm_paper_drawdown_pct','pm_resolved_estimates','pm_brier_gain','pm_shadow_roi','pm_edge_over_control','pm_graduation_ready','pm_breaker_active'); DELETE FROM metric_registry WHERE metric IN ('pm_paper_return_pct','pm_paper_drawdown_pct','pm_resolved_estimates','pm_brier_gain','pm_shadow_roi','pm_edge_over_control','pm_graduation_ready','pm_breaker_active'); DELETE FROM control_registry WHERE control IN ('pm-circuit-breaker','pm-graduation-gate','pm-sports-filter','pm-min-gap'); DELETE FROM objective_space WHERE objective_key = 'objective:pm-information-edge';
-- spof-review: the review loop writes its metrics and heartbeat to qnfo-audit through the AUDIT binding; if that write fails the tick still completes (best effort, logged, reported as published "error") and the fleet's heartbeat watch sees the missing beat. Second path: GET https://markets.q08.org/api/charter serves the same evidence directly.
-- CAUSE-MAPPED: the eight pm_* metrics below map to the existing cause key `measurement` in metric_breach_cause in this same file.
-- TRIGGER-EXEMPT: pm_paper_return_pct, pm_paper_drawdown_pct, pm_resolved_estimates and pm_edge_over_control are progress and context readings for the four triggered metrics (a drawdown breach is the pm_breaker_active trigger; a weak edge over the favourite shows in pm_shadow_roi and pm_brier_gain); a trigger on each would file four duplicate issues for one cause.
--
-- PM-CHARTER-1 (2026-11-09, charter pillar personal). Owner direction 2026-11-09: following price momentum is pointless; q08-prediction-markets must forecast independently from better
-- information, tie into q08's forecasts and signal sources, run as a self-managing fleet program with feedback loops, and only ever trade real money (a funded Polymarket account) after
-- paper trading shows a clear benefit of the internal signals. This file registers the program the way the rest of the fleet is registered:
--   metrics     eight runner-written pm_* readings (the worker's review loop writes metric_registry.last_value each tick) and four triggers that file breaches as issues;
--   controls    the circuit breaker (a pause with a reason and a 24 h expiry), the graduation gate, the sports filter and the self-tuned minimum gap, each with its alternate path;
--   objective   the program's objective, probationary until the graduation gate has passed on paper;
--   decision    the design decision and its prediction, to be scored by the calibration scorer.
-- Live trading is not built: the worker has no live executor. The graduation gate (GET https://markets.q08.org/api/charter) only reports; the owner step is IDENTITY-BOUND (issue PM-LIVE-1).

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, baseline, target, owner, disposition_actor, refresh_cadence, warning_band, kill_band, state, refresh_class) VALUES
 ('pm_paper_return_pct', 'operational', 'target', 'percent change of paper equity against the 10,000 starting cash', 'q08-prediction-markets review loop (TRADES_DB pt_equity) -> metric_registry.last_value; GET https://markets.q08.org/api/state', '0 on 2026-11-09', '> 0', 'q08-prediction-markets', 'observed with the graduation evidence; the breaker acts on drawdown', '*/5', '< -5', '< -15', 'NEW', 'runner'),
 ('pm_paper_drawdown_pct', 'operational', 'guard', 'percent the latest paper equity is below its peak', 'q08-prediction-markets review loop (TRADES_DB pt_equity)', '0 on 2026-11-09', '< 15', 'q08-prediction-markets', 'the circuit breaker pauses new entries at 15 (pm-circuit-breaker)', '*/5', '> 10', '> 15', 'NEW', 'runner'),
 ('pm_resolved_estimates', 'operational', 'target', 'estimates whose market has resolved (outcome known), the sample the proof is computed on', 'q08-prediction-markets review loop (TRADES_DB pt_estimate.outcome)', '0 on 2026-11-09', '>= 100', 'q08-prediction-markets', 'graduation needs 100 (pm-graduation-gate)', '*/5', '< 100', '< 30', 'NEW', 'runner'),
 ('pm_brier_gain', 'operational', 'target', 'mean of (market-price Brier minus model Brier) over resolved estimates; positive means the model beats the price; 0 until 30 estimates have resolved', 'q08-prediction-markets review loop (evaluate)', '0 (no data) on 2026-11-09', '> 0', 'q08-prediction-markets', 'analytics_metric_triggers -> evaluateMetricTriggers (qnfo-fleet-control) files the breach', '*/5', '< 0', '< -0.02', 'NEW', 'runner'),
 ('pm_shadow_roi', 'operational', 'target', 'mean return per unit staked of a flat bet on every qualifying estimate at the price seen then, after slippage; 0 until 30 qualifying estimates have resolved', 'q08-prediction-markets review loop (evaluate)', '0 (no data) on 2026-11-09', '> 0', 'q08-prediction-markets', 'analytics_metric_triggers -> evaluateMetricTriggers (qnfo-fleet-control) files the breach', '*/5', '< 0', '< -0.05', 'NEW', 'runner'),
 ('pm_edge_over_control', 'operational', 'target', 'shadow ROI of the signal bets minus the ROI of backing whichever side the market already favours on the same markets; positive means the information beats following the market', 'q08-prediction-markets review loop (evaluate)', '0 (no data) on 2026-11-09', '> 0', 'q08-prediction-markets', 'graduation needs it above zero with 95% confidence (pm-graduation-gate)', '*/5', '< 0', '< -0.05', 'NEW', 'runner'),
 ('pm_graduation_ready', 'operational', 'target', '1 when every criterion of the PM-CHARTER-1 graduation gate holds on paper, else 0; it never switches anything on', 'q08-prediction-markets review loop (graduation); GET https://markets.q08.org/api/charter', '0 on 2026-11-09', '0 until the evidence exists, then 1', 'q08-prediction-markets', 'analytics_metric_triggers -> evaluateMetricTriggers files the notice; the next step is the owner IDENTITY-BOUND issue PM-LIVE-1', '*/5', '> 0', '> 0', 'NEW', 'runner'),
 ('pm_breaker_active', 'operational', 'guard', '1 while the circuit breaker is pausing new signal entries (drawdown at the breaker, or the model significantly worse than the price), else 0', 'q08-prediction-markets review loop (TRADES_DB pt_control.paused_until)', '0 on 2026-11-09', '0', 'q08-prediction-markets', 'analytics_metric_triggers -> evaluateMetricTriggers (qnfo-fleet-control) files the breach', '*/5', '> 0', '> 0', 'NEW', 'runner');

