INSERT OR IGNORE INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes) VALUES
 ('pm_breaker_active', 'The prediction-market circuit breaker is pausing new paper entries', 'metric_registry', 'gt', 0, 5,
  'Pillar personal (PM-CHARTER-1). GET https://markets.q08.org/api/charter: control.paused_reason says whether it was a drawdown at 15% or a model significantly worse than the market price, and decisions[] holds the logged change with its rollback. Read evaluation (brier_gain, shadow_roi, edge_over_control) and the last predictions in /api/state, find which evidence source or prompt produced the misses, and change the lever (the evidence in fetchNews, the prompt or ensemble in askModel, the gap rule in decide) with a test that fails on the miss. The pause expires by itself after 24 hours; do not clear it by hand.
code-task: repo=qnfo-workers path=q08-prediction-markets/worker.js
code-anchor: async function askModel(env, m, news, model) {',
  'qnfo-fleet-control', 'agent_issues', 24, 1, 'PM-CHARTER-1'),
 ('pm_brier_gain', 'The prediction-market model is not beating the market price', 'metric_registry', 'lt', 0, 5,
  'Pillar personal (PM-CHARTER-1). The model-minus-price Brier gain is negative over at least 30 resolved estimates (the metric reads 0 before that). GET https://markets.q08.org/api/charter and compare evaluation.brier_model with brier_market, then calibration.buckets: is the model overconfident (high buckets resolving below their probability) or just noisy? Fix at the cause: shrink toward the price (the blend has its own Brier in evaluation.brier_blend), widen evidence, or drop a model family that disagrees most. Add a test with the miss pattern in engine.test.mjs.
code-task: repo=qnfo-workers path=q08-prediction-markets/worker.js
code-anchor: export function evaluate(rows, minEdge = CFG.MIN_EDGE, cfg = CFG) {',
  'qnfo-fleet-control', 'agent_issues', 168, 1, 'PM-CHARTER-1'),
 ('pm_shadow_roi', 'The prediction-market signal bets lose money on paper', 'metric_registry', 'lt', -0.05, 5,
  'Pillar personal (PM-CHARTER-1). Shadow ROI (a flat bet on every qualifying estimate) is below -5% over at least 30 resolved qualifying estimates. GET https://markets.q08.org/api/charter: evaluation.shadow_roi against control_roi (backing the favourite). The self-tuning loop already raises the minimum gap on a significantly negative ROI (reviewActions); if that is not enough, change the gap rule or the universe (universe.min_volume24, horizon) with a test.
code-task: repo=qnfo-workers path=q08-prediction-markets/worker.js
code-anchor: export function reviewActions(ev, ctx, cfg = CFG) {',
  'qnfo-fleet-control', 'agent_issues', 168, 1, 'PM-CHARTER-1'),
 ('pm_graduation_ready', 'The prediction-market program has met every paper-trading graduation criterion', 'metric_registry', 'gt', 0, 3,
  'Pillar personal (PM-CHARTER-1). GET https://markets.q08.org/api/charter: graduation.ready is true, so on paper the internal signals beat the market price and the market favourite with 95% confidence over the required sample. This is a notice, not an instruction to go live: the worker has no live executor. The next step belongs to the owner and is the IDENTITY-BOUND issue PM-LIVE-1 (wallet-signed key, API key, funding, jurisdiction and terms review); its default stays paper. The fleet verifies the evidence (re-run evaluate on the resolved estimates, read the decisions log for tuning that could have fitted the sample) and records the check on that issue.',
  'qnfo-fleet-control', 'agent_issues', 168, 1, 'PM-CHARTER-1');

INSERT OR REPLACE INTO control_registry (control, location, kind, guards_against, critical_path, disposition, disposition_state, alternate_path, alternate_tested_at, evidence, reviewed_at) VALUES
 ('pm-circuit-breaker', 'q08-prediction-markets pt_control.paused_until (review loop)', 'pause', 'paper losses (and later real ones) running on when drawdown reaches 15% or the model is significantly worse than the market price over 30 or more resolved estimates', 0, 'keep', 'applied',
  'the pause carries its reason and expires after 24 hours by itself; exits, estimation and scoring continue while paused; every pause is a pt_decision row with its rollback (DELETE FROM pt_control WHERE key IN (''paused_until'',''paused_reason''))', '2026-11-09',
  'tick.test.mjs "the circuit breaker pauses new entries (estimates continue), logs the decision with a rollback, and expires"; engine.test.mjs reviewActions; metric pm_breaker_active with a trigger', '2026-11-09T00:00:00Z'),
 ('pm-graduation-gate', 'q08-prediction-markets graduation() and GET /api/charter', 'gate', 'real money being risked on a program with no statistical evidence that its information beats the market price and the market favourite', 1, 'keep', 'applied',
  'none needed: the gate only reports and the worker has no live executor, so the alternate to a closed gate is the paper executor that already runs; opening it is an owner step (IDENTITY-BOUND issue PM-LIVE-1)', NULL,
  'engine.test.mjs "graduation: stays paper until every criterion holds, and says why" (ready never means live; CHARTER.live.enabled is false); metric pm_graduation_ready with a trigger', '2026-11-09T00:00:00Z'),
 ('pm-sports-filter', 'q08-prediction-markets isSports() in parseMarket and tick', 'filter', 'trading game results, where q08 has no information advantage and the open markets were dominated by them (owner concern 2026-11-09)', 0, 'keep', 'applied',
  'a sport the keyword list misses is still held to the 14-day horizon, the volume floor and the three-model agreement rule before any trade; extend SPORTS_RE with a test', '2026-11-09',
  'engine.test.mjs "isSports flags games and leagues but not finance or politics"; tick.test.mjs "sports and long-dated markets are never estimated or traded"', '2026-11-09T00:00:00Z'),
 ('pm-min-gap', 'q08-prediction-markets pt_control.min_edge (review loop self-tuning)', 'guard', 'trading on gaps too small to survive slippage and estimate noise; the loop moves the minimum gap between 8 and 20 points, two points up on a significantly negative result and one point down only on proof', 0, 'keep', 'applied',
  'the default is 10 points; DELETE FROM pt_control WHERE key = ''min_edge'' restores it; each change is a pt_decision row', '2026-11-09',
  'engine.test.mjs "reviewActions: pause on drawdown or a significantly worse model, widen the gap, narrow it only on proof" (floor and ceiling)', '2026-11-09T00:00:00Z');

INSERT OR IGNORE INTO control_alternate_probes (control, probe_sql, window_note, enabled) VALUES
 ('pm-circuit-breaker', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'' AND ts < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'')) THEN ''the q08-prediction-markets heartbeat is older than 30 minutes, so the review loop that applies this control is not running'' WHEN NOT EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'') AND (SELECT reviewed_at FROM control_registry WHERE control = ''pm-circuit-breaker'') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-6 hours'') THEN ''q08-prediction-markets never published a heartbeat since this control was registered'' WHEN (SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''pm_paper_drawdown_pct'') >= 15 AND COALESCE((SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''pm_breaker_active''), 0) = 0 AND (SELECT last_refreshed FROM metric_registry WHERE metric = ''pm_paper_drawdown_pct'') > strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'') THEN ''drawdown is at or above the 15% breaker but the breaker is not active'' ELSE ''ok'' END AS observed', '30 min: the review loop runs every 5 minutes and publishes the drawdown and the breaker state together; a drawdown at the breaker with the breaker inactive for a fresh reading means the pause did not apply. The behaviour itself is replayed in q08-prediction-markets/tick.test.mjs', 1),
 ('pm-graduation-gate', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'' AND ts < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'')) THEN ''the q08-prediction-markets heartbeat is older than 30 minutes, so the review loop that applies this control is not running'' WHEN NOT EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'') AND (SELECT reviewed_at FROM control_registry WHERE control = ''pm-graduation-gate'') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-6 hours'') THEN ''q08-prediction-markets never published a heartbeat since this control was registered'' WHEN COALESCE((SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''pm_graduation_ready''), 0) = 1 AND COALESCE((SELECT CAST(last_value AS REAL) FROM metric_registry WHERE metric = ''pm_resolved_estimates''), 0) < 100 THEN ''the graduation gate reads ready with fewer than 100 resolved estimates'' ELSE ''ok'' END AS observed', '30 min: both readings are written by the same tick; the gate may never read ready on a sample smaller than the charter minimum. Criteria replayed in engine.test.mjs', 1),
 ('pm-sports-filter', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'' AND ts < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'')) THEN ''the q08-prediction-markets heartbeat is older than 30 minutes, so the review loop that applies this control is not running'' WHEN NOT EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'') AND (SELECT reviewed_at FROM control_registry WHERE control = ''pm-sports-filter'') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-6 hours'') THEN ''q08-prediction-markets never published a heartbeat since this control was registered'' ELSE ''ok'' END AS observed', '30 min: the filter is part of parseMarket in the same worker whose heartbeat is checked; its classification is replayed in engine.test.mjs (isSports)', 1),
 ('pm-min-gap', 'SELECT ''ok'' AS expected, CASE WHEN EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'' AND ts < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-30 minutes'')) THEN ''the q08-prediction-markets heartbeat is older than 30 minutes, so the review loop that applies this control is not running'' WHEN NOT EXISTS (SELECT 1 FROM fleet_heartbeat WHERE worker = ''q08-prediction-markets'') AND (SELECT reviewed_at FROM control_registry WHERE control = ''pm-min-gap'') < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-6 hours'') THEN ''q08-prediction-markets never published a heartbeat since this control was registered'' ELSE ''ok'' END AS observed', '30 min: the self-tuning runs inside the same review loop whose heartbeat is checked; floor and ceiling are replayed in engine.test.mjs (reviewActions)', 1);

INSERT OR IGNORE INTO objective_space (objective_key, class, statement, source) VALUES
 ('objective:pm-information-edge', 'novel', 'Show on paper, with 95% confidence, that q08''s independently researched probabilities on short-term non-sports prediction-market questions beat the market price and beat backing the market favourite, on a sample of at least 100 resolved estimates over 30 days; only then ask the owner whether to fund a live account. Until then the program stays on paper.', 'owner direction 2026-11-09 (prediction markets charter PM-CHARTER-1)');

INSERT INTO decision_log (actor, assumption, action, evidence, outcome, blast_radius, rollback_path, capability_gain, predicted_outcome, reach_gain, surfaces_tested) VALUES
 ('claude-session', 'A price-following strategy has no information edge; the literature (Halawi et al. 2024: retrieval-augmented ensemble Brier 0.179 against 0.149 for the human crowd) says a model alone does not beat the crowd, so any edge must be demonstrated against the price rather than assumed',
  'Removed the momentum and fade strategies from q08-prediction-markets and replaced them with a three-model ensemble estimate from Hacker News and GDELT evidence, never shown the price, with a proof harness (Brier against the price, shadow ROI, a control that backs the favourite), a circuit breaker, bounded self-tuning of the minimum gap and a graduation gate that only reports',
  'q08-prediction-markets 1.5.0: 32 tests including synthetic worlds where better information passes the gate and a worse model does not; migrations/2026-11-09-pm-charter.sql registers the metrics, triggers and controls',
  'paper trading only; the worker has no live executor and no wallet or exchange key', 'the paper book of one worker and eight metric_registry rows; no real money, no other worker',
  'revert the PR; DELETE the rows named in the Rollback line of migrations/2026-11-09-pm-charter.sql; DELETE FROM pt_control restores the default gap and clears a pause',
  'a self-measuring program that proves or disproves its own edge and halts itself when wrong', 'pm_resolved_estimates >= 30 within 336 h', 'q08 forecast calibration can reuse resolved-in-days outcomes (issue PM-Q08-TIE-1)', 'engine and tick tests; dashboard in a real browser at 375 px');
